alter table public.fletya_tariff_versions add column stair_per_level numeric(10,2) check(stair_per_level between 0 and 10000), add column elevator_per_site numeric(10,2) check(elevator_per_site between 0 and 10000), add column free_wait_minutes integer check(free_wait_minutes between 0 and 1440), add column wait_per_minute numeric(10,2) check(wait_per_minute between 0 and 1000);
alter table public.fletya_tariff_versions alter column stair_per_level set default 150, alter column elevator_per_site set default 100, alter column free_wait_minutes set default 20, alter column wait_per_minute set default 5;
insert into public.fletya_tariff_versions(reason,included_km,parcel_base,parcel_km,moving_base,moving_km,materials_base,materials_km,helper_price,helper_hours,helper_overtime) select 'Suplementos aprobados para Pruebas',included_km,parcel_base,parcel_km,moving_base,moving_km,materials_base,materials_km,helper_price,helper_hours,helper_overtime from public.fletya_tariff_versions where effective_at<=now() order by effective_at desc,created_at desc limit 1;